## Why This Is Asked
Tests knowledge of Trie data structures, deduplication strategies, and efficient prefix queries—essential skills for building autocomplete systems.

## Key Concepts
- Trie with per-node subtree counts for O(1) prefix counting
- Deduplication via global set to maintain word uniqueness
- Prefix-based retrieval with controlled result limits
- Lexicographic ordering through systematic child traversal

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked
This question assesses dynamic programming fundamentals through practical string segmentation, testing understanding of both top-down memoization and bottom-up tabulation approaches.

## Key Concepts
- Dynamic Programming: memoization vs. tabulation
- String matching optimization (startsWith, trie)
- Time and space trade-offs between DP approaches
- State definition and transition logic

## Code Example
```javascript
// Top-down memoized solution
function minWordSegmentsTopDown(s, dict) {
  const n = s.length;
  const memo = Array(n + 1).fill(-1);
  memo[n] = 0;

  function dfs(i) {
    if (memo[i] !== -1) return memo[i];
    let minSegs = Infinity;
    for (const word of dict) {
      if (s.startsWith(word, i)) {
        const result = dfs(i + word.length);
        if (result !== -1) {
          minSegs = Math.min(minSegs, 1 + result);
        }
      }
    }
    memo[i] = minSegs === Infinity ? -1 : minSegs;
    return memo[i];
  }
  return dfs(0);
}

// Bottom-up tabulated solution
function minWordSegmentsBottomUp(s, dict) {
  const n = s.length;
  const dp = Array(n + 1).fill(Infinity);
  dp[n] = 0;

  for (let i = n - 1; i >= 0; i--) {
    for (const word of dict) {
      if (s.startsWith(word, i)) {
        if (dp[i + word.length] !== Infinity) {
          dp[i] = Math.min(dp[i], 1 + dp[i + word.length]);
        }
      }
    }
  }
  return dp[0] === Infinity ? -1 : dp[0];
}
```

## Complexity Analysis
- **Time:** O(n × m × L) where n = |s|, m = dict size, L = avg word length. Using a Trie reduces this to O(n × L).
- **Space:** O(n) for the memo/DP array.

## Why This Is Asked

